window.RP_SESSION={"id":"S-4185f70d4c10","messages":[{"id":"RP-II-0203112","time":"2026-09-23T08:31:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"굿모닝 일리아. 좋은아침이에요.","characters":["P-b522cca806d0"]},{"id":"RP-II-0203113","time":"2026-09-23T08:34:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"오늘은 꽤나 한적한 하루랍니다. 의뢰를 떠나는 날도 아니고. 딱히 특별히 일정이 있는 날도 아니죠.\n\n모험가나, 용병이 갖고 있는 직업적 특수성일까요? 한가할때는 진짜 더할나위 없이 한가해진답니다.\n\n그런 적적한 아침 속에서 에스텔은...","characters":["P-b522cca806d0"]},{"id":"RP-II-0203114","time":"2026-09-23T08:34:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-b522cca806d0"]},{"id":"RP-II-0203115","time":"2026-09-23T08:34:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'에스텔 벨라시타'의 체력 판정 :\n[7] + [3] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0203116","time":"2026-09-23T08:35:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"\"끙, 차. 후...이정도면 반정도 됐으려나요.\"\n\n에스텔은 웬 포대자루를 잔뜩 옮기고 있습니다!","characters":["P-b522cca806d0"]},{"id":"RP-II-0203117","time":"2026-09-23T08:36:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"아침부터 왜 노가다를 하고있냐고요?\n부식적재작업? 그게 뭐죠?","characters":["P-b522cca806d0"]},{"id":"RP-II-0203118","time":"2026-09-23T08:36:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"아무튼 사정을 살펴보자면,","characters":["P-b522cca806d0"]},{"id":"RP-II-0203119","time":"2026-09-23T08:41:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"이른 아침이었습니다.\n에스텔은 평소처럼 교회를 갔답니다. 딱히 뭐어...신앙에 이유를 붙일 필요는 없겠죠?\n\n거리의 한적함과는 다르게. 교회라는 곳은 본래 이른 새벽, 그리고 아침 즈음이 가장 분주한 법이죠.\n\n\"네. 반가워요. 안녕하세요? 좋은 아침이에요!\"\n\n평소처럼 아는 분들 모르는 분들 가리지 않고 인사하고, 기도하고 있었는데.\n\n어라, 평소보다 예배가 굉장히 빨리 끝난거 있죠?","characters":["P-b522cca806d0"]},{"id":"RP-II-0203120","time":"2026-09-23T08:44:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"그래서 신부님께 이유를 물어보니...\n\n\"아, 반갑습니다 자매님. 음. 오늘은 인근 빈민가에 급식을 배분할 예정인지라. 조금 일정을 빠르게 끝냈습니다.\"","characters":["P-b522cca806d0"]},{"id":"RP-II-0203121","time":"2026-09-23T08:44:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"오. 그렇군요. 빈민구제. 봉사. 구휼활동.","characters":["P-b522cca806d0"]},{"id":"RP-II-0203122","time":"2026-09-23T08:45:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"바로 직후 에스텔이 취한 행동은,\n\n\"저도 따라가도 될까요?\"\n\n자세히 살펴보지 않아도 충분하겠죠?","characters":["P-b522cca806d0"]},{"id":"RP-II-0203123","time":"2026-09-23T08:45:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"그 결과가 바로 지금이랍니다.","characters":["P-b522cca806d0"]},{"id":"RP-II-0203124","time":"2026-09-23T08:47:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"끙차 끙차.\n에스텔은 밀가루가 든 포대를 들고, 끌려가듯 옮기고 있습니다.","characters":["P-b522cca806d0"]},{"id":"RP-II-0203125","time":"2026-09-23T08:47:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"좋아요. 이쯤에서 한 번 물어보죠.","characters":["P-b522cca806d0"]},{"id":"RP-II-0203126","time":"2026-09-23T08:50:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"혹시 그녀말고도 봉사를 나온 인원이 있을까요?\n\n여느 의뢰와는 다르게 보수도 없고.\n개인적인 여가시간을 소모해서 진행되며.\n그렇다고 '영웅적인 행보'는 또 아닌지라, 이름을 날리거나 명성을 얻지도 못할거에요.","characters":["P-b522cca806d0"]},{"id":"RP-II-0203127","time":"2026-09-23T08:50:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"그래도 함께 나온 분이 계실까요?","characters":["P-b522cca806d0"]},{"id":"RP-II-0203128","time":"2026-09-23T09:10:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"좋아요. 좋아요. 보채지 않을게요.\n모든 활동을 동료와 함께해야 한다는 보장은 없잖아요?","characters":["P-b522cca806d0"]},{"id":"RP-II-0203129","time":"2026-09-23T09:11:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"당장 둘러보면 그녀를 제외하곤 현장에 길드원은 딱히 보이지 않는 것 같네요.","characters":["P-b522cca806d0"]},{"id":"RP-II-0203130","time":"2026-09-23T09:12:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"다음 기회가 있겠죠!","characters":["P-b522cca806d0"]},{"id":"RP-II-0203131","time":"2026-09-23T09:12:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"그래서, 구츌활동은 별다른 시츄에이션 없이 잘 마무리 됐으려나요?","characters":["P-b522cca806d0"]},{"id":"RP-II-0203132","time":"2026-09-23T09:12:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-b522cca806d0"]},{"id":"RP-II-0203133","time":"2026-09-23T09:12:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 11 = 11\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-II-0203134","time":"2026-09-23T09:12:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"네. 신부님이 신경 써주신 덕분에, 별다른 문제 없이 잘 끝나게 됐답니다.","characters":["P-b522cca806d0"]},{"id":"RP-II-0203135","time":"2026-09-23T09:12:00+09:00","room":"RP II","name":"에스텔 벨라시타 / 교회 신부","profile":"에스텔 벨라시타","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b522cca806d0"]},{"id":"RP-II-0203136","time":"2026-09-23T09:12:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]},{"id":"RP-II-0203137","time":"2026-09-23T15:09:00+09:00","room":"RP II","name":"헥터","profile":"헥터","identity":"unresolved","type":"dialogue","body":"!독백","characters":[]},{"id":"RP-II-0203138","time":"2026-09-23T15:09:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"조용히, 피어오르는\n또 다른 누군가의 이야기.\n\n※해당 RP는 중참이 불가합니다.\n※중참 희망시 해당 기입자께 문의 바랍니다.","characters":[]}]};
